class Home extends StatefulWidget{const Home({super.key,required this.token,required this.logout});final String token;final VoidCallback logout;@override State<Home> createState()=>_Home();}
class _Home extends State<Home>{List data=[];List areas=[];String business='',staff='';bool loading=true;Timer? timer;Map<String,String> get h=>{'content-type':'application/json','authorization':'Bearer '+widget.token};@override void initState(){super.initState();load();_push();timer=Timer.periodic(const Duration(seconds:5),(_)=>load());}@override void dispose(){timer?.cancel();super.dispose();}Future<void> _push()async{try{if(Firebase.apps.isEmpty)return;await FirebaseMessaging.instance.requestPermission();final t=await FirebaseMessaging.instance.getToken();if(t==null)return;final p=await SharedPreferences.getInstance();var d=p.getString('valet_device_id');if(d==null){d=DateTime.now().microsecondsSinceEpoch.toString();await p.setString('valet_device_id',d);}await http.post(Uri.parse(api+'/api/valet/push-token'),headers:h,body:jsonEncode({'token':t,'deviceId':d}));FirebaseMessaging.instance.onTokenRefresh.listen((n){http.post(Uri.parse(api+'/api/valet/push-token'),headers:h,body:jsonEncode({'token':n,'deviceId':d}));});}catch(_){}}
