   if(qrCode==null)...[const SizedBox(height:12),TextField(controller:p,decoration:const InputDecoration(labelText:'Plaka',border:OutlineInputBorder()))],
   const SizedBox(height:12),
   if(areas.isEmpty)const Text('İşletme panelinden önce bir park alanı eklenmeli.',style:TextStyle(color:Colors.orangeAccent)) else DropdownButtonFormField<String>(initialValue:selectedArea,decoration:const InputDecoration(labelText:'Park alanı',border:OutlineInputBorder()),items:areas.map<DropdownMenuItem<String>>((x)=>DropdownMenuItem(value:x['name'].toString(),child:Text(x['name'].toString()))).toList(),onChanged:(v)=>setSheet(()=>selectedArea=v)),
   const SizedBox(height:16),FilledButton(onPressed:areas.isEmpty?null:()async{if(p.text.trim().isEmpty)return;final r=await http.post(Uri.parse(api+'/api/valet/accept'),headers:h,body:jsonEncode({'plate':p.text.trim(),'qrCode':qrCode,'parkingArea':selectedArea}));if(r.statusCode<300&&c.mounted)Navigator.pop(c);await load();},style:FilledButton.styleFrom(backgroundColor:lime,foregroundColor:Colors.black,padding:const EdgeInsets.all(16)),child:const Text('Aracı Valeye Al',style:TextStyle(fontWeight:FontWeight.w900)))
  ]))));
